// FACT SETTINGS of the tab EU OEE Fact write: dry run and the line list.
// In: one table message of a build tab (msg.table, site, month, out, rows).
// Out 1: the message with msg.path = the line list file; cfg in flow
// context. Out 2: a log line for a skipped job (MONTH_JOBS, FIRST_DAY).

// true: nothing is written, the log shows what would be written.
var DRY_RUN = true;
// The line list (Unique Machine Name, Dept, Area, Product Type): In EU
// Report of the fact = the line is in this file (as the month files).
var LINE_LIST = 'report/Dim/Machine_Names_EU.csv';
// false: a month job of a build tab (from/to) writes no fact file, because
// the month files EU_OEE_Fact_<YYYY-MM>.parquet already hold the history
// and a second file of the same days would count them twice.
var MONTH_JOBS = false;
// The first day this tab writes (the cutover): the month files hold the
// days before it (docs/eu-oee-fact-flows.md, "Cutover").
var FIRST_DAY = '2026-11-10';

var shared = glob.get('cfg');
if (!shared) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not run'
  });
  node.error('global cfg is missing: deploy or run the Config tab first');
  return [null, null];
}

var isMonth = /^\d{4}-\d{2}$/.test(msg.month);
var reason = '';
if (isMonth && !MONTH_JOBS) {
  reason = 'a month job; EU_OEE_Fact takes day jobs only (MONTH_JOBS)';
} else if (!isMonth && String(msg.month).slice(0, 10) < FIRST_DAY) {
  reason = 'before FIRST_DAY ' + FIRST_DAY + ' (the month files hold it)';
}
if (reason) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'skipped ' + msg.month
  });
  var text = 'SKIPPED: ' + msg.table + ' ' + msg.site + ' ' + msg.month;
  text += ' is ' + reason;
  return [null, {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  }];
}

var cfg = Object.assign({}, shared);
cfg.dryRun = {
  EU_OEE_Fact: DRY_RUN
};
flow.set('cfg', cfg);

msg.path = shared.root + '/' + LINE_LIST;
node.status({
  fill: DRY_RUN ? 'yellow' : 'green',
  shape: 'dot',
  text: (DRY_RUN ? 'DRY RUN ' : 'WRITE ') + msg.site + ' ' + msg.month
});
return [msg, null];

// Maps the rows of one table message to the 65 columns of EU_OEE_Fact.
// In: msg.rows and msg.table (Plan_OPT_EU, Time_Utilisation_EU,
// Daily_Losses_EU or Run Rate), msg.payload = the parsed line list.
// Out 1: msg.rows = fact rows, msg.fileTag. Out 2: a check log line.

// Union, never a join (docs/eu-oee-fact-run-rate.md).
var RECORD_TYPE = {
  'Plan_OPT_EU': 'Plan',
  'Time_Utilisation_EU': 'Time Utilisation',
  'Daily_Losses_EU': 'Loss',
  'Run Rate': 'Run Rate'
};
// The part of the file name per record type.
var FILE_TAG = {
  'Plan': 'plan',
  'Time Utilisation': 'tu',
  'Loss': 'loss',
  'Run Rate': 'rr'
};
// Daily_Losses_EU names -> fact names.
var LOSS_RENAMES = {
  'Date': 'Event Date',
  'ShiftStartDate': 'Date',
  'Shift colour': 'Shift Colour',
  'target': 'Loss Target'
};
// Loss Target is a fraction (glidepath / 100): 6 decimals, as the month
// files (0.072, not 0.07200000000000001).
var ROUND_6 = [
  'Loss Target'
];
var COLUMNS = [
  'Record Type',
  'Date',
  'SiteName',
  'MachineName',
  'Unique Machine Name',
  'ShiftName',
  'Dept',
  'Area',
  'Product Type',
  'In EU Report',
  'AreaName',
  'PartName',
  'Good Parts',
  'Capacity',
  'Total Time',
  'Planned OpT',
  'OEE Time',
  'Downtime Units',
  'Product Key',
  'UPDT Target',
  'PDT Target',
  'OEE Target',
  'Defect Parts',
  'OEE',
  'Shift Colour',
  'ShiftStartTime',
  'Target',
  'Targets Key',
  'Brand',
  'Unit Size',
  'Unit Count/Format',
  'Extra Info',
  'Data Source',
  'source_hours',
  'loaded_at',
  'Event Date',
  'Time',
  'OEELossLvl3Group',
  'OEELossLvl3SubGroup',
  'OEELossLvl3Desc',
  'Duration',
  'Breakdown Types',
  'Comment',
  'Volume Key',
  'Loss Units',
  'Equipment',
  'Loss Target Key',
  'Value',
  'Volume Total',
  'Loss Final Level',
  'Batch ID',
  'Equipment Loss Key',
  'Lvl 3 Loss Name',
  'Time in Mins',
  'Shift Time',
  'Loss Target',
  'comment_count',
  'OEE Time Total',
  'Total Time Total',
  'Planned OPT Total',
  'All Time',
  'In EU Report Source',
  'RR Hours',
  'RR Good Parts',
  'RR Capacity'
];

var type = RECORD_TYPE[msg.table];
if (!type) {
  node.error('EU_OEE_Fact: unknown table ' + msg.table);
  return null;
}

// Line list: Unique Machine Name -> Dept, Area, Product Type.
function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}
var lines = {};
(Array.isArray(msg.payload) ? msg.payload : []).forEach(function (row) {
  var key = text(row['Unique Machine Name']);
  if (key) {
    lines[key] = row;
  }
});
var lineCount = Object.keys(lines).length;
if (!lineCount) {
  msg.failed = (msg.failed || []).concat(['line list empty or missing']);
}

// Line list value, else the value of the row (an empty cell is null).
function pick(line, row, column) {
  var value = line ? text(line[column]) : '';
  if (value !== '') {
    return value;
  }
  return row[column] === undefined ? null : row[column];
}

var unknown = {};
var listed = 0;
var out = msg.rows.map(function (source) {
  var row = {};
  Object.keys(source).forEach(function (name) {
    var to = type === 'Loss' && LOSS_RENAMES[name] ? LOSS_RENAMES[name] : name;
    if (COLUMNS.indexOf(to) === -1) {
      unknown[name] = true;
      return;
    }
    row[to] = source[name];
  });
  var fact = {};
  COLUMNS.forEach(function (column) {
    fact[column] = row[column] === undefined ? null : row[column];
  });
  ROUND_6.forEach(function (column) {
    if (typeof fact[column] === 'number') {
      fact[column] = Math.round(fact[column] * 1e6) / 1e6;
    }
  });
  var line = lines[text(source['Unique Machine Name'])];
  fact['Record Type'] = type;
  fact['In EU Report Source'] = row['In EU Report'] === undefined ?
    null : row['In EU Report'];
  fact['In EU Report'] = Boolean(line);
  fact['Dept'] = pick(line, row, 'Dept');
  fact['Area'] = pick(line, row, 'Area');
  fact['Product Type'] = pick(line, row, 'Product Type');
  if (line) {
    listed++;
  }
  return fact;
});

msg.rows = out;
msg.recordType = type;
msg.fileTag = FILE_TAG[type];
var check = msg.site + ' ' + msg.month + ' ' + type + ': ' + out.length;
check += ' fact rows, ' + listed + ' on the line list (' + lineCount;
check += ' lines)';
var extra = Object.keys(unknown);
if (extra.length) {
  check += ', columns not in EU_OEE_Fact left out: ' + extra.join(' / ');
}
node.status({
  fill: extra.length ? 'yellow' : 'green',
  shape: 'dot',
  text: msg.site + ' ' + msg.month + ' ' + type + ': ' + out.length
});
return [
  msg,
  {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] CHECK ' + check
  }
];

// Decides what happens with the table EU_OEE_Fact.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'EU_OEE_Fact';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';
if (msg.out) {
  sizes += ' to ' + msg.out;
}

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file of one site, day (or month) and record type:
// <out>/EU_OEE_Fact/site=<Site>/EU_OEE_Fact_<day>_<tag>_<source>.parquet,
// tag plan, tu, loss or rr. In: the parquet node output. Out: msg.path.
// A rerun of the day replaces only this record type of this source.
msg.path = msg.out + '/EU_OEE_Fact/site=' + msg.site;
msg.path += '/EU_OEE_Fact_' + msg.month + '_' + msg.fileTag;
msg.path += '_' + msg.source + '.parquet';
msg.filename = msg.path.split('/').pop();
return msg;

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'eu-oee-fact';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Notes the time of the newest log line of the tab in global context
// lastLog_<flow>. In: every log line (a tap behind the log formatter). Out:
// nothing. A new line clears done_<flow>, so the next quiet period is shown.
var FLOW = 'eu-oee-fact';
glob.set('lastLog_' + FLOW, Date.now());
glob.set('done_' + FLOW, false);
var status = glob.get('runStatus_' + FLOW);
if (status) {
  var row = msg.payload || {};
  var line = String(row.message || msg.line || '');
  status.lastBeatAt = new Date().toISOString();
  status.lastLog = line.slice(0, 160);
  if (row.level === 'failed' || row.level === 'error') {
    status.state = 'failed';
  }
  glob.set('runStatus_' + FLOW, status);
}
return null;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'eu-oee-fact';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
flow.set('logDone', done.slice(-KEEP_IDS));

msg.payload = old + lines.join('\n') + '\n';
msg.path = path;
delete msg.logRows;
return msg;
